import{_ as p,a0 as a,w as r,s as d,ao as l,I as i,x as o,a1 as n,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"如何在 Win8 上禁用 UEFI 以安裝Linux | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Win8 上禁用 UEFI 以安裝Linux | LCTT (201405) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Win8 上禁用 UEFI 以安裝Linux | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Win8 上禁用 UEFI 以安裝Linux | LCTT (201405) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201405/How To Disable UEFI Secure Boot In Windows 8 & 8.1","title":"如何在 Win8 上禁用 UEFI 以安裝Linux","tag":"201405","desc":""},"relativePath":"201405/How To Disable UEFI Secure Boot In Windows 8 & 8.1.md","filePath":"[post].md"}'),u={name:"201405/How To Disable UEFI Secure Boot In Windows 8 & 8.1.md"};function w(g,t,m,f,I,W){const s=a("Link");return r(),d("div",null,[t[11]||(t[11]=l('<h1 id="如何在-win8-上禁用-uefi-以安裝linux" tabindex="-1">如何在 Win8 上禁用 UEFI 以安裝Linux <a class="header-anchor" href="#如何在-win8-上禁用-uefi-以安裝linux" aria-label="Permalink to “如何在 Win8 上禁用 UEFI 以安裝Linux”">​</a></h1><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/Disable_Secure_Boot_Windows8_UEFI.jpeg" alt=""></p><p>現在，如果你買了預裝 Windows 的電腦，一般都是 Windows8 或 Windows8.1。從 Windows8 開始，微軟用 UEFI 取代了 BIOS。儘管 UEFI 不是微軟發明的，在 Windows8 之前它就已經存在。比如某些 Mac 設備使用 UEFI 已經有一段時間了。</p><p>UEFI 有“安全啓動”這個特點，引導程序只會啓動那些得到 UEFI 固件簽署的引導裝載程序。此安全功能可以防止 Rootkit 類的惡意軟件，並提供了額外的安全層。但它有一個缺點，如果你想在 Win8的電腦上雙引導 Linux ，安全機制會阻止這樣做。這篇文章告訴大家如何在Win8中禁用UEFI安全引導，以支持 Linux 的雙系統啓動。</p><h3 id="在windows-8-8-1上禁用uefi安全啓動" tabindex="-1">在Windows 8 &amp; 8.1上禁用UEFI安全啓動 <a class="header-anchor" href="#在windows-8-8-1上禁用uefi安全啓動" aria-label="Permalink to “在Windows 8 &amp; 8.1上禁用UEFI安全啓動”">​</a></h3><p>關於安全啓動，充斥着各種各樣的説法。由於這些傳聞，有些人幾乎認為在預裝 Windows8 的電腦上啓動 Linux 是不可能的。雖然在 ARM PC上這是真的，但是在基於 Intel 的系統上安全引導是可以被禁用的。老實説，<strong>禁用UEFI安全啓動</strong>不是一個艱鉅的任務，同樣的雙啓動的 Linux 與 Windows 8 也不是。</p><p>雖然在 BIOS 時代，訪問 BIOS 是相當簡單的，在啓動的時候按 F10 或 F12 鍵即可。但是在 UEFI 的世界裏，就不一樣了。要訪問 UEFI 設置，你就必須進入到 Windows 中去。讓我們來看看如何在 Windows 8 中訪問 UEFI 設置來禁用安全啓動。</p><h4 id="step-1-進入pc設置" tabindex="-1">Step 1: 進入PC設置 <a class="header-anchor" href="#step-1-進入pc設置" aria-label="Permalink to “Step 1: 進入PC設置”">​</a></h4><p>點擊 Windows+I 按鈕進入 Windows 設置界面。在底部，你會看到更改電腦設置的選項。點擊它。</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/Disable_Secure_Boot_1.jpeg" alt=""></p><h4 id="step-2-進入高級啓動" tabindex="-1">Step 2: 進入高級啓動 <a class="header-anchor" href="#step-2-進入高級啓動" aria-label="Permalink to “Step 2: 進入高級啓動”">​</a></h4><p>在 Windows 8 和 Windows8.1 上，PC設置有一個細微的差別。依照你使用的系統不同，分別按照下面介紹的各個步驟進行操作：</p><p>Windows 8的：在Windows 8中，你需要進入通用PC設置，並選擇<strong>高級啓動</strong>，然後點擊<strong>立即重新啓動：</strong></p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/Change_PC_Settings_Windows8.jpg" alt=""></p><p><strong>Window 8.1</strong>的：在 Windows8.1，從左側邊欄點擊<strong>更新和恢復</strong>：</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/Disable_Secure_Boot_Windows8_2.jpeg" alt=""></p><p>然後單擊<strong>立即重新啓動</strong>下的<strong>高級啓動</strong>：</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/Disable_Secure_Boot_Windows8_3.jpeg" alt=""></p><p>不要擔心！這之後並不會立刻重新啓動，而是會在下一步看到一些選項。</p><h4 id="step-4-進入uefi設置" tabindex="-1">Step 4: 進入UEFI設置 <a class="header-anchor" href="#step-4-進入uefi設置" aria-label="Permalink to “Step 4: 進入UEFI設置”">​</a></h4><p>當您單擊了立即重新啓動按鈕，在下一頁屏幕中，你將會看到一些可以選擇的選項。這裏選擇<strong>疑難解答</strong>：</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/Troubleshoot_Windows8.jpg" alt=""></p><p>在<strong>疑難解答</strong>菜單中，選擇<strong>高級選項</strong>：</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/Troubleshoot_Windows8_1.jpg" alt=""></p><p>在高級選項菜單中，選擇<strong>UEFI固件設置</strong>：</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/Troubleshoot_Windows8_2.jpg" alt=""></p><p>接下來，在UEFI設置裏，點擊<strong>重新啓動</strong>按鈕重新啓動您的系統，就會看到類似BIOS一樣的界面。</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/Troubleshoot_Windows8_3.jpg" alt=""></p><h4 id="step-5-在-uefi-中禁用安全啓動" tabindex="-1">Step 5: 在 UEFI 中禁用安全啓動 <a class="header-anchor" href="#step-5-在-uefi-中禁用安全啓動" aria-label="Permalink to “Step 5: 在 UEFI 中禁用安全啓動”">​</a></h4><p>這個時候，你一定已經啓動到 UEFI 工具界面。你可以在這裏更改各種設置。但我們想要做的，只是禁用安全啓動選項，允許 Ubuntu 或者任何其它 Linux 版本的雙啓動。</p><p>移動到啓動選項卡，在那裏你會發現<strong>安全引導</strong>選項被設置為啓用。使用箭頭鍵進入安全引導選項，然後按<strong>回車鍵</strong>來選擇它。 <em>使用+或 - 來改變它的值。按</em>* F10 鍵保存更改<strong>並退出 UEFI 設置。</strong>提示時確認即可**。</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/Disable_Secure_Boot_Windows8.jpg" alt=""></p><p>接下來，您將會正常引導到 Windows。現在，您就支持雙啓動 Windows8 與 Ubuntu 或其它 Linux 操作系統了。過段時間裏我會寫關於如何雙啓動 Ubuntu 與 Windows 8 UEFI 的教程。敬請關注。</p><p>我希望這個教程可以幫助您禁用 Windows8 和 Windows8.1 的安全引導。如有任何疑問或建議，歡迎隨時評論。</p><hr>',35)),i("p",null,[t[1]||(t[1]=o("via: ",-1)),n(s,{href:"http://itsfoss.com/disable-uefi-secure-boot-in-windows-8/"},{default:e(()=>[...t[0]||(t[0]=[o("http://itsfoss.com/disable-uefi-secure-boot-in-windows-8/",-1)])]),_:1})]),i("p",null,[t[4]||(t[4]=o("譯者：",-1)),n(s,{href:"https://github.com/MikeCoder"},{default:e(()=>[...t[2]||(t[2]=[o("MikeCoder",-1)])]),_:1}),t[5]||(t[5]=o(" 校對：",-1)),n(s,{href:"https://github.com/carolinewuyan"},{default:e(()=>[...t[3]||(t[3]=[o("Caroline",-1)])]),_:1})]),i("p",null,[t[8]||(t[8]=o("本文由 ",-1)),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[6]||(t[6]=[o("LCTT",-1)])]),_:1}),t[9]||(t[9]=o(" 原創翻譯，",-1)),n(s,{href:"http://linux.cn/"},{default:e(()=>[...t[7]||(t[7]=[o("Linux中國",-1)])]),_:1}),t[10]||(t[10]=o(" 榮譽推出",-1))])])}const F=p(u,[["render",w]]);export{h as __pageData,F as default};
